// The screen menus of @ui8kit/app-shared (nav/<ScreenName>, generated by compose-gen) for the live previews, loaded on demand by
// package name; the `nav` source of previewLoader (load.ts). Moved from apps/stock/src/lib/preview.ts (an import.meta.glob over
// ../../../../packages/shared/app/src/nav). One entry per generated file: nav.test.ts fails when compose-gen adds or drops a screen.
export type ScreenNav = { links: readonly unknown[]; current: string };
type NavModule = { navOf: (area: string) => ScreenNav };

export const NAVS: Record<string, () => Promise<NavModule>> = {
  ThemeAccountPortalScreen: () => import("@ui8kit/app-shared/nav/ThemeAccountPortalScreen"),
  ThemeCommerceShopScreen: () => import("@ui8kit/app-shared/nav/ThemeCommerceShopScreen"),
  ThemeContentBlogScreen: () => import("@ui8kit/app-shared/nav/ThemeContentBlogScreen"),
  ThemeDashboardConsoleScreen: () => import("@ui8kit/app-shared/nav/ThemeDashboardConsoleScreen"),
  ThemeMarketingLandingScreen: () => import("@ui8kit/app-shared/nav/ThemeMarketingLandingScreen"),
  ThemeMarketingPricingScreen: () => import("@ui8kit/app-shared/nav/ThemeMarketingPricingScreen"),
  ThemeMarketingProductScreen: () => import("@ui8kit/app-shared/nav/ThemeMarketingProductScreen"),
  ThemeOnboardingFlowScreen: () => import("@ui8kit/app-shared/nav/ThemeOnboardingFlowScreen"),
  ThemePromoCampaignScreen: () => import("@ui8kit/app-shared/nav/ThemePromoCampaignScreen"),
  ThemeSupportCenterScreen: () => import("@ui8kit/app-shared/nav/ThemeSupportCenterScreen"),
};

/** the menu of a screen for an area; undefined for a screen without a menu module */
export async function screenNav(screen: string, area: string): Promise<ScreenNav | undefined> {
  const load = NAVS[screen];
  return load ? (await load()).navOf(area) : undefined;
}
